<?php $this->layout('layouts/admin', ['title' => 'Quản lý tour', 'pageTitle' => 'Danh sách tour', 'activeMenu' => 'tour']) ?>
<?php $this->start('page') ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 fw-bold mb-1">Tất cả hành trình</h2><p class="text-secondary mb-0"><?= count($tours) ?> tour đang được quản lý</p></div><a href="/admin/tours/create" class="btn btn-warning fw-bold"><i class="bi bi-plus-lg me-1"></i>Thêm tour</a></div>
<div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Tour</th><th>Danh mục</th><th>Thời lượng</th><th>Giá</th><th>Địa điểm</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach($tours as $tour):?><tr><td>#<?= (int)$tour['tourId'] ?></td><td><div class="d-flex align-items-center gap-3"><img src="<?= $this->e($tour['imageUrl'] ?: '/images/tour-placeholder.svg') ?>" class="rounded-3 object-fit-cover" style="width:64px;height:48px" alt=""><strong><?= $this->e($tour['title']) ?></strong></div></td><td><?= $this->e($tour['categoryName']) ?></td><td><?= (int)$tour['numberDays'] ?> ngày</td><td class="fw-semibold"><?= number_format((float)$tour['basePrice'],0,',','.') ?>₫</td><td><span class="d-inline-block text-truncate" style="max-width:220px"><?= $this->e($tour['locationNames'] ?: '—') ?></span></td><td><div class="d-flex justify-content-end gap-1"><a href="/tours/detail/<?= (int)$tour['tourId'] ?>" target="_blank" class="btn btn-sm btn-outline-primary"><i class="bi bi-eye"></i></a><a href="/admin/tours/edit/<?= (int)$tour['tourId'] ?>" class="btn btn-sm btn-outline-dark"><i class="bi bi-pencil"></i></a><form action="/admin/tours/delete/<?= (int)$tour['tourId'] ?>" method="POST" onsubmit="return confirm('Xóa tour này?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$tours):?><tr><td colspan="7" class="text-center text-secondary py-5">Chưa có tour.</td></tr><?php endif;?></tbody></table></div></div>
<?php $this->stop() ?>
